        "{used} of {limit} in use ({jobs} by jobs, {recordings} by recordings)": "zajęte: {used} z {limit} (przez zadania: {jobs}, przez nagrania: {recordings})",
        "Through {proxy}: sites see {address}": "Przez {proxy}: strony widzą {address}",
